div.script:
document.getElementById('games').onclick = function() {
  var w = window.open('about:blank', '_blank');
  if (!w) {
    alert('Please allow pop-ups and try again.');
    return;
  }
  var iframe = w.document.createElement('iframe');
  iframe.src = 'https://s3.amazonaws.com/prageru-server/mathematics.html';
  iframe.style.cssText = 'position:fixed;top:0;left:0;width:100%;height:100%;border:0';
  w.document.title = 'Games';
  w.document.body.style.cssText = 'margin:0;background:#000';
  w.document.body.appendChild(iframe);
};
